			keζ0 := int(int64(tmpζ0) >> 52)
			mζ0 := math.Float64frombits(iyζ0 - uint64(int64(tmpζ0)>>52)<<52)
			tζ0 := &logT[int(float64(mζ0*256)+0.5)-192]
			invcζ0 := tζ0[0]
			pζ0 := float64(mζ0 * invcζ0)
			peζ0 := math.FMA(mζ0, invcζ0, -pζ0)
			rζ0 := pζ0 - 1
